int lengthOfLongestSubstring(string s) {
    int last[128]; fill(last, last+128, -1);
    int best = 0, l = 0;
    for (int r = 0; r < s.size(); r++) {
        unsigned char c = s[r];
        if (last[c] >= l) l = last[c] + 1;      // teleport left
        last[c] = r;
        best = max(best, r - l + 1);
    }
    return best;
}

