// count subarrays with AT MOST m odd numbers
long long atMost(vector<int>& a, int m){
    long long cnt = 0; int l = 0, odds = 0;
    for (int r = 0; r < a.size(); r++) {
        odds += a[r] & 1;
        while (odds > m) odds -= a[l++] & 1;
        cnt += r - l + 1;                 // every suffix-ending here
    }
    return cnt;
}
// exactly k odds = atMost(k) - atMost(k-1)

