def at_most(a, m):
    cnt = l = 0
    odds = 0
    for r, x in enumerate(a):
        odds += x & 1
        while odds > m:
            odds -= a[l] & 1; l += 1
        cnt += r - l + 1                 # every suffix ending here
    return cnt
# exactly k = at_most(k) - at_most(k-1)
